-- STAGING ONLY 487: preserve unknown Job Card header hours as NULL in canonical source-row receipts.
BEGIN;SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-487-unknown-hours-receipt-contract',0));DO $g$ BEGIN IF current_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827036000' AND name='486_owner_document_receipt_contract') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827036000') OR (SELECT is_nullable FROM information_schema.columns WHERE table_schema='public' AND table_name='pdc_jobcard_attachment_source_row_receipts' AND column_name='estimated_hours')<>'NO' OR pg_get_constraintdef((SELECT oid FROM pg_constraint WHERE conrelid='public.pdc_jobcard_attachment_source_row_receipts'::regclass AND conname='pdc_jobcard_attachment_source_row__estimated_hours_source_check'),true) IS DISTINCT FROM 'CHECK (estimated_hours_source = ''job_card''::text)' THEN RAISE EXCEPTION 'PDC_487_TARGET_HEAD_OR_HOURS_CONTRACT_MISMATCH' USING errcode='55000';END IF;END $g$;ALTER TABLE public.pdc_jobcard_attachment_source_row_receipts ALTER COLUMN estimated_hours DROP NOT NULL;ALTER TABLE public.pdc_jobcard_attachment_source_row_receipts DROP CONSTRAINT pdc_jobcard_attachment_source_row_receipts_estimated_hours_chec,DROP CONSTRAINT pdc_jobcard_attachment_source_row__estimated_hours_source_check,ADD CONSTRAINT pdc_jobcard_attachment_source_row_receipts_estimated_hours_check CHECK(estimated_hours IS NULL OR estimated_hours BETWEEN 0 AND 999.99),ADD CONSTRAINT pdc_jobcard_attachment_source_row_receipts_hours_source_check CHECK((estimated_hours IS NOT NULL AND estimated_hours_source='job_card') OR (estimated_hours IS NULL AND estimated_hours_source='owner_supplied_document_unknown'));CREATE TABLE public.pdc_uid635_unknown_hours_contract_repairs_487(receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action_key text NOT NULL UNIQUE CHECK(action_key='uid635-null-hours-source-row-receipts'),failed_uid bigint NOT NULL CHECK(failed_uid=635),failed_stock text NOT NULL CHECK(failed_stock='13000775'),failed_constraint text NOT NULL CHECK(failed_constraint='estimated_hours_not_null'),repair_scope text NOT NULL CHECK(repair_scope='unknown header hours remain NULL with owner_supplied_document_unknown provenance; never converted to zero'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_uid635_unknown_hours_contract_repairs_487 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_uid635_unknown_hours_contract_repairs_487 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_uid635_unknown_hours_contract_repairs_487(action_key,failed_uid,failed_stock,failed_constraint,repair_scope) VALUES('uid635-null-hours-source-row-receipts',635,'13000775','estimated_hours_not_null','unknown header hours remain NULL with owner_supplied_document_unknown provenance; never converted to zero');DO $p$ BEGIN IF (SELECT is_nullable FROM information_schema.columns WHERE table_schema='public' AND table_name='pdc_jobcard_attachment_source_row_receipts' AND column_name='estimated_hours')<>'YES' OR pg_get_constraintdef((SELECT oid FROM pg_constraint WHERE conrelid='public.pdc_jobcard_attachment_source_row_receipts'::regclass AND conname='pdc_jobcard_attachment_source_row_receipts_hours_source_check'),true) NOT LIKE '%owner_supplied_document_unknown%' OR EXISTS(SELECT 1 FROM public.pdc_email_monitor_pilot WHERE enabled OR automatic_rule_application OR automatic_authenticated_jobcards) THEN RAISE EXCEPTION 'PDC_487_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $p$;INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827037000','487_unknown_hours_receipt_contract',ARRAY['Repair the exact second constraint exposed by the controlled UID635 rehearsal','Allow canonical source-row receipt estimated_hours to remain NULL only with owner_supplied_document_unknown provenance','Never convert unknown hours to zero','Keep UID635 Inbox-retained and one-shot writer contained pending exact retry','Production untouched']);COMMIT;
